import {html, isServer, nothing} from 'lit';
import {msg} from '@lit/localize';
import {customElement} from 'lit/decorators.js';
import {unsafeHTML} from 'lit/directives/unsafe-html.js';
import {AIUXWidgetElement, decorators} from '@servicenow/aiux-components-core';
import {RecordAPIKey} from '@servicenow/aiux-components-record';
import {withPlaybookFormContext} from '@servicenow/aiux-components-playbook';

const {category, discoverable} = decorators;

// <aiux-record-form>'s edit-mode attribute values. Inlined as string literals
// to avoid taking a dependency on the control package for two stable constants.
const FORM_EDIT_MODE_DEFAULT = 'default';
const FORM_EDIT_MODE_DISPLAY_ONLY = 'display-only';

/**
 * Default playbook activity renderer (SDK-built widget).
 *
 * One widget handles three shapes, distinguished by the activity props:
 *   - Instruction  : no form_fields and no form_view -> render description only.
 *   - Questionnaire: form_fields.value === 'vars'     -> show only vars.* fields.
 *   - Form         : form_fields.value is a comma list (e.g.
 *                    "description,short_description") -> show only those; or a
 *                    form_view (e.g. "collect_data") already scopes the fields.
 *
 * Importing withPlaybookFormContext from @servicenow/aiux-components-playbook
 * (kept EXTERNAL, served by karuna at runtime) joins this widget to the host's
 * module-singleton graph, so RecordContext / playbookActivityContext resolve to
 * the same instances the live <aiux-record-provider> and playbook-card use. The
 * mixin supplies _recordContext, _formApi, _actionsApi, the
 * playbookActivityContext subscription, and the form lifecycle hooks; field
 * visibility (form_fields) is applied by the mixin's _applyFieldVisibility.
 *
 * @element playbook-default-form
 */
@discoverable(true)
@category('platform')
@customElement('playbook-default-form')
export default class PlaybookDefaultForm extends withPlaybookFormContext(
  AIUXWidgetElement
) {
  // Activity content renders client-side — see the SSR caveat in README.md.
  static ssr = false;

  static aiContext = {
    description:
      'The current playbook step: a form the user fills out, or read-only instruction text when the step has no fields.',
    bestFor:
      'When the user asks about the current task, the form fields, wants to fill in values, or needs help completing the playbook step.'
  };

  static properties = {
    description: {type: Object},
    table: {type: Object},
    associated_table: {type: Object},
    record: {type: Object},
    associated_record: {type: Object},
    form_view: {type: Object},
    form_fields: {type: Object}
  };

  get _isDirty() {
    return this._formApi?.isDirty?.() ?? false;
  }

  // Instruction activities carry neither a field list nor a form view -- only
  // a description. Forms/questionnaires always carry form_fields and/or
  // form_view.
  get _isInstruction() {
    return !this.form_fields?.value && !this.form_view?.value;
  }

  connectedCallback() {
    super.connectedCallback();
    this._pushState();
    if (!isServer) this._pushWidgetContext();
  }

  disconnectedCallback() {
    super.disconnectedCallback();
    this._lastPushedState = undefined;
  }

  updated(changedProperties) {
    super.updated(changedProperties);
    if (isServer) return;
    this._pushState();
    this._pushWidgetContext();
  }

  _pushWidgetContext() {
    const table = this.table?.value ?? this.associated_table?.value;
    const recordId = this.record?.value ?? this.associated_record?.value;
    this.setAiContext({
      table,
      recordId,
      activityContextId: this._activityContext?.activityContextId,
      isDirty: this._isDirty
    });
  }

  _pushState() {
    const recordContext = this._recordContext;
    const isDirty = this._isDirty;
    if (
      recordContext === this._lastPushedState?.recordContext &&
      isDirty === this._lastPushedState?.isDirty
    ) {
      return;
    }
    this._lastPushedState = {recordContext, isDirty};
    this.dispatchEvent(
      new CustomEvent('playbook-activity-renderer:update', {
        bubbles: true,
        composed: true,
        detail: {recordContext, isDirty}
      })
    );
  }

  render() {
    const actCtx = this._activityContext;

    // The description is shown for every activity that has one. Only the form
    // differs: instructions never render it; forms/questionnaires render the
    // description above the form.
    const description = this.description?.value;
    const descriptionTemplate = description
      ? html`<div class="text-sm text-base-content/70">
          ${unsafeHTML(description)}
        </div>`
      : nothing;

    // Instruction: description only, never a record form.
    if (this._isInstruction) {
      return description
        ? descriptionTemplate
        : html`<p class="text-sm text-base-content/40 italic" role="status">
            ${msg('No instruction content available.')}
          </p>`;
    }

    const effectiveTable = this.table?.value ?? this.associated_table?.value;
    const recordId = this.record?.value ?? this.associated_record?.value;
    const formView = this.form_view?.value;
    const activityContextId = actCtx?.activityContextId;

    if (!effectiveTable || !recordId) {
      return html`
        ${descriptionTemplate}
        <p class="text-sm text-base-content/40 italic" role="status">
          ${msg('No record data available.')}
        </p>
      `;
    }

    // Read-only unless the card found a visible DA that requires form fields
    // (formReadOnly is provided via playbookActivityContext).
    const editMode = actCtx?.formReadOnly
      ? FORM_EDIT_MODE_DISPLAY_ONLY
      : FORM_EDIT_MODE_DEFAULT;

    return html`
      ${descriptionTemplate}
      <aiux-record-provider
        table=${effectiveTable}
        .sysId=${recordId}
        view=${formView || ''}
        context-id=${activityContextId || ''}
        .requiredAPIs=${[RecordAPIKey.Actions]}
      >
        <aiux-record-form edit-mode=${editMode} hide-section-headers></aiux-record-form>
      </aiux-record-provider>
    `;
  }
}
